package org.pms.silverocean.database.pms;
import org.pms.silverocean.database.pms.entities.AffiliatePayout;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import org.springframework.data.jpa.repository.Lock;import jakarta.persistence.LockModeType;import java.math.BigDecimal;import java.util.List;import java.util.Optional;
public interface AffiliatePayoutRepo extends JpaRepository<AffiliatePayout,Long>{List<AffiliatePayout> findTop100ByAffiliateUserIdAndActiveTrueOrderByCreatedOnDesc(long id);List<AffiliatePayout> findTop200ByActiveTrueOrderByCreatedOnDesc();boolean existsByAffiliateUserIdAndStatusAndActiveTrue(long id,String status);@Query("SELECT COALESCE(SUM(p.amount),0) FROM AffiliatePayout p WHERE p.affiliateUserId=:userId AND p.status IN ('REQUESTED','PROCESSING') AND p.active=true")BigDecimal pending(long userId);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("SELECT p FROM AffiliatePayout p WHERE p.id=:id AND p.active=true")Optional<AffiliatePayout> findForUpdate(long id);}
